"""Nested-resource API with ownership semantics.

Users are simulated via an `X-User-ID` header. Ownership rules:
  - A project is visible/modifiable only to its owner.
  - Any other user gets 404 (never 403), so existence is not leaked.
  - Tasks are addressed as /projects/{pid}/tasks/{tid}; a task id that
    exists under a *different* project of your own also yields 404,
    because lookups are scoped to (project_id, task_id) jointly.
"""

import sqlite3
from contextlib import closing
from pathlib import Path
from typing import Annotated

from fastapi import Depends, FastAPI, Header, HTTPException, status
from pydantic import BaseModel, Field

DB_PATH = Path(__file__).parent / "app.db"

app = FastAPI(title="Projects & Tasks (ownership-scoped)")

# --------------------------------------------------------------------------
# Database helpers
# --------------------------------------------------------------------------


def get_db() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    try:
        yield conn
    finally:
        conn.close()


def init_db() -> None:
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS projects (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT NOT NULL DEFAULT '',
                owner_id TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
            CREATE TABLE IF NOT EXISTS tasks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                project_id INTEGER NOT NULL REFERENCES projects(id)
                    ON DELETE CASCADE,
                title TEXT NOT NULL,
                done INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
            """
        )
        conn.commit()


init_db()

# --------------------------------------------------------------------------
# Auth simulation (X-User-ID header)
# --------------------------------------------------------------------------

DbDep = Annotated[sqlite3.Connection, Depends(get_db)]


def current_user(x_user_id: str = Header(...)) -> str:
    """Simulated auth: the caller *is* whatever ID the header carries."""
    if not x_user_id.strip():
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED, detail="X-User-ID required"
        )
    return x_user_id


UserDep = Annotated[str, Depends(current_user)]


def _project_or_404(db: sqlite3.Connection, project_id: int):
    row = db.execute(
        "SELECT * FROM projects WHERE id = ?", (project_id,)
    ).fetchone()
    if row is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Project not found"
        )
    return row


def owned_project_or_404(
    db: DbDep,
    user_id: UserDep,
    project_id: int,
):
    """Return the project only if it exists AND belongs to the caller.

    Non-owned or missing projects both yield an identical 404 so that
    existence is never leaked to non-owners.
    """
    row = _project_or_404(db, project_id)
    if row["owner_id"] != user_id:
        # Deliberately indistinguishable from "does not exist".
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Project not found"
        )
    return row


OwnedProjectDep = Annotated[dict, Depends(owned_project_or_404)]

# --------------------------------------------------------------------------
# Schemas
# --------------------------------------------------------------------------


class ProjectIn(BaseModel):
    name: str = Field(min_length=1, max_length=200)
    description: str = Field(default="", max_length=2000)


class ProjectPatch(BaseModel):
    name: str | None = Field(default=None, min_length=1, max_length=200)
    description: str | None = Field(default=None, max_length=2000)


class TaskIn(BaseModel):
    title: str = Field(min_length=1, max_length=500)


class TaskPatch(BaseModel):
    title: str | None = Field(default=None, min_length=1, max_length=500)
    done: bool | None = None


def project_out(row: sqlite3.Row) -> dict:
    return {
        "id": row["id"],
        "name": row["name"],
        "description": row["description"],
        "owner_id": row["owner_id"],
    }


def task_out(row: sqlite3.Row) -> dict:
    return {
        "id": row["id"],
        "project_id": row["project_id"],
        "title": row["title"],
        "done": bool(row["done"]),
    }


# --------------------------------------------------------------------------
# /projects — CRUD, owned by creating user
# --------------------------------------------------------------------------


@app.post("/projects", status_code=status.HTTP_201_CREATED)
def create_project(body: ProjectIn, db: DbDep, user_id: UserDep):
    cur = db.execute(
        "INSERT INTO projects (name, description, owner_id) VALUES (?, ?, ?)",
        (body.name, body.description, user_id),
    )
    db.commit()
    return project_out(_project_or_404(db, cur.lastrowid))


@app.get("/projects")
def list_projects(db: DbDep, user_id: UserDep):
    rows = db.execute(
        "SELECT * FROM projects WHERE owner_id = ? ORDER BY id", (user_id,)
    ).fetchall()
    return [project_out(r) for r in rows]


@app.get("/projects/{project_id}")
def get_project(project: OwnedProjectDep):
    return project


@app.patch("/projects/{project_id}")
def update_project(
    body: ProjectPatch, project_id: int, db: DbDep, project: OwnedProjectDep
):
    fields = body.model_dump(exclude_unset=True)
    if not fields:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="No fields to update",
        )
    sets = ", ".join(f"{k} = ?" for k in fields)
    db.execute(
        f"UPDATE projects SET {sets} WHERE id = ?", (*fields.values(), project_id)
    )
    db.commit()
    return project_out(_project_or_404(db, project_id))


@app.delete("/projects/{project_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_project(project_id: int, db: DbDep, project: OwnedProjectDep):
    db.execute("DELETE FROM projects WHERE id = ?", (project_id,))
    db.commit()
    return None


# --------------------------------------------------------------------------
# /projects/{pid}/tasks — nested CRUD, always scoped to the owned project
# --------------------------------------------------------------------------


def task_in_project_or_404(
    db: sqlite3.Connection, project_id: int, task_id: int
) -> sqlite3.Row:
    """Jointly-scoped lookup: a task id belonging to any other project
    (even another project of the same user) simply does not exist here."""
    row = db.execute(
        "SELECT * FROM tasks WHERE id = ? AND project_id = ?",
        (task_id, project_id),
    ).fetchone()
    if row is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Task not found"
        )
    return row


@app.post(
    "/projects/{project_id}/tasks", status_code=status.HTTP_201_CREATED
)
def create_task(body: TaskIn, db: DbDep, project: OwnedProjectDep):
    cur = db.execute(
        "INSERT INTO tasks (project_id, title) VALUES (?, ?)",
        (project["id"], body.title),
    )
    db.commit()
    return task_out(task_in_project_or_404(db, project["id"], cur.lastrowid))


@app.get("/projects/{project_id}/tasks")
def list_tasks(db: DbDep, project: OwnedProjectDep):
    rows = db.execute(
        "SELECT * FROM tasks WHERE project_id = ? ORDER BY id",
        (project["id"],),
    ).fetchall()
    return [task_out(r) for r in rows]


@app.get("/projects/{project_id}/tasks/{task_id}")
def get_task(task_id: int, db: DbDep, project: OwnedProjectDep):
    return task_out(task_in_project_or_404(db, project["id"], task_id))


@app.patch("/projects/{project_id}/tasks/{task_id}")
def update_task(
    body: TaskPatch, task_id: int, project_id: int, db: DbDep,
    project: OwnedProjectDep,
):
    task_in_project_or_404(db, project_id, task_id)  # scope check first
    fields = {}
    data = body.model_dump(exclude_unset=True)
    if not data:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="No fields to update",
        )
    if "title" in data:
        fields["title"] = data["title"]
    if "done" in data:
        fields["done"] = int(data["done"])
    sets = ", ".join(f"{k} = ?" for k in fields)
    db.execute(
        f"UPDATE tasks SET {sets} WHERE id = ? AND project_id = ?",
        (*fields.values(), task_id, project_id),
    )
    db.commit()
    return task_out(task_in_project_or_404(db, project_id, task_id))


@app.delete(
    "/projects/{project_id}/tasks/{task_id}",
    status_code=status.HTTP_204_NO_CONTENT,
)
def delete_task(task_id: int, project_id: int, db: DbDep, project: OwnedProjectDep):
    task_in_project_or_404(db, project_id, task_id)
    db.execute("DELETE FROM tasks WHERE id = ?", (task_id,))
    db.commit()
    return None

